#define main old_thermal_main
#include "../reactor-protium/search.cpp"
#undef main
#include <filesystem>
namespace fs=std::filesystem;
struct Ranked { Cand c; double score=0, raw=0, margin=0; };
static const string types="KVEOICPR124";
static const int frMaxF=(int)PI("frMaxF"),frChrono=max(1,(int)PI("frChrono"));
static int randint(int n){return n?int(rng()%n):0;}
static bool adjacencyOK(const string&g){for(int i=0;i<N;i++) if(g[i]=='I')for(int j:a[i])if(g[j]=='V')return false;return true;}
static double calculateCost(const string&g,int av,int hs,int ex,int re,int ch,int wi,int li){array<int,128> n{};for(char x:g)n[(unsigned char)x]++;return PR.fuel(n)+PR.upgrades(av,hs,ex,re,ch,wi,li)+PR.parts(n);}
static Ranked evaluate(string g,int av,int hs,int ex,int re,int ch,int wi,int li,double b,int id){Ranked out;out.score=-1e100;if(!adjacencyOK(g))return out;array<int,128> n{};for(char x:g)n[(unsigned char)x]++;int fuels=n['1']+n['2']+n['4'];if(fuels<1||fuels>frMaxF||n['P']<1||n['V']<1||n['O']<1)return out;double cost=calculateCost(g,av,hs,ex,re,ch,wi,li);if(cost>b)return out;
 double H=0,P=0,held=0;for(int i=0;i<N;i++)if(int co=core(g[i])){int pulse=co==1?1:co==2?4:12,r=0,cs=0;for(int j:a[i]){pulse+=core(g[j]);r+=g[j]=='R';cs+=g[j]=='C';}double heat=pulse*pulse*M.fuelHeat/co;H+=heat;P+=pulse*M.fuelPow*(1+M.refl*r);if(cs)held+=heat;}
 double cooling=n['V']*M.vr0*(1+M.ventBoost*(M.bAv+av)*n['K']);double hc=n['P']*M.hullPer;if(cooling<H||hc<=H)return out;double fuelcost=PR.fuel(n);
 if(held>0)P*=M.boost(max(1.,held-hc*M.drain));double sales=M.sales(n['K'],wi,li);double net=min(P,sales)-fuelcost*1e6/M.fuelLife;out.c={g,av,hs,ex,re,ch,cost,min(P,sales),H,cooling,id};out.raw=net;out.margin=(cooling-H)/max(1.,H);out.score=net*(M.bCh+ch);return out;}
static string randomGrid(){string g(N,'K');int fuels=1+randint(frMaxF);for(int z=0;z<fuels;z++){int i=randint(N);for(int t=0;t<100&&g[i]!='K';t++)i=randint(N);g[i]='1';for(int j:a[i])if(g[j]=='K'&&randint(100)<85)g[j]='R';}
 int count=randint(N/2)+N/3;for(int t=0;t<count;t++){int i=randint(N);if(g[i]!='K')continue;int r=randint(100);g[i]=r<21?'V':r<37?'O':r<41?'I':r<44?'C':r<55?'P':r<61?'E':'K';}return g;}
static void mutate(string&g){int times=1+randint(18);for(int t=0;t<times;t++){int i=randint(N),r=randint(100);if(r<14){int j=randint(N);swap(g[i],g[j]);}else if(r<19){int j=a[i].empty()?i:a[i][randint((int)a[i].size())];swap(g[i],g[j]);}else if(r<25){g[i]='K';}else{static const string weighted="KKKKKKKKKKKKKKKKKKKKKKVVVVVVVVVVOOOOOPPPPKKKKKCCIIEERRR";if(g[i]=='1'||g[i]=='2'||g[i]=='4'){if(randint(100)<90)continue;}g[i]=weighted[randint((int)weighted.size())];}}}
static void save(const Ranked&r,const string&file){ofstream f(file);auto &c=r.c;f<<setprecision(15)<<c.power<<' '<<c.heat<<' '<<c.cool<<' '<<c.cost<<' '<<c.av<<' '<<c.hs<<' '<<c.ex<<' '<<c.re<<' '<<c.ch<<' '<<c.seed<<'\n';for(int y=0;y<16;y++)f<<c.g.substr(y*19,19)<<'\n';}
int main(int argc,char**argv){long long loops=PI("frAttempts");uint32_t seed=(uint32_t)PI("frSeed");double b=PR.budget;int verify=(int)PI("frVerify");string output="run-"+to_string(seed);if(loops<1||b<=0||verify<1){cerr<<"попыток, бюджет и топ должны быть > 0\n";return 1;}fs::create_directories(output);rng.seed(seed);for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i+19<N)a[i].push_back(i+19);}
 string reference;{ifstream f(S("frRef"));string line;getline(f,line);for(int y=0;y<16&&getline(f,line);y++)reference+=line;}if(reference.size()!=N){cerr<<"эталон "<<S("frRef")<<" не найден или не 19x16 с заголовком\n";return 2;}
 vector<Ranked> top;Ranked seedLeader=evaluate(reference,1,0,0,0,0,0,0,b,-1);if(seedLeader.score>-1e90)top.push_back(seedLeader);string stable;{ifstream f(S("frStable"));string line;getline(f,line);for(int y=0;y<16&&getline(f,line);y++)stable+=line;}if(stable.size()==N){Ranked sr=evaluate(stable,1,1,0,1,0,0,0,b,-2);if(sr.score>-1e90)top.push_back(sr);else cerr<<"stable reference rejected by analytic screening\n";}long long screened=0;unordered_set<string> seen;seen.reserve((size_t)min(loops,1000000LL));
 for(long long z=0;z<loops;z++){string g;if(z%6==0)g=randomGrid();else if(z%6==1||top.empty())g=reference;else if(z%6==2&&stable.size()==N)g=stable;else g=top[randint(min((int)top.size(),20))].c.g;if(z%17!=0)mutate(g);int av=randint(2),hs=randint(2),ex=randint(2),re=randint(2),ch=randint(frChrono)==0,wi=randint(2),li=randint(2);if(z%3&& !top.empty()){auto& parent=top[randint(min((int)top.size(),20))].c;av=parent.av;hs=parent.hs;ex=parent.ex;re=parent.re;ch=parent.ch;}
 // Set fuel count freely by cell mutations but leave a guaranteed way to keep surviving parents.
 if(z%6==2&&stable.size()==N){av=1;hs=1;ex=0;re=1;ch=0;wi=0;li=0;}if(z%6==1){av=1;hs=0;ex=0;re=0;ch=0;wi=0;li=0;}Ranked r=evaluate(g,av,hs,ex,re,ch,wi,li,b,int(z));if(r.score<=-1e90)continue;screened++;if(!seen.insert(g).second)continue;top.push_back(move(r));sort(top.begin(),top.end(),[](auto&x,auto&y){return x.score>y.score;});if(top.size()>size_t(max(verify*5,100)))top.resize(max(verify*5,100));if(z&&z%100000==0)cerr<<"attempts="<<z<<" analytic_pass="<<screened<<" best_screen_score="<<top.front().score<<'\n';}
 // Full simulation of the highest-ranking unique candidates, including faults, both iteration orders and cooldown.
 cerr<<"симуляция топ-"<<verify<<"...\n";
 ofstream csv(output+"/verified.csv");csv<<"seed,net_B_per_tick,score,screen_cooling_margin,cost_Qa,normal_forward,normal_reverse,outlet_fault_forward,outlet_fault_reverse,vent_fault_forward,vent_fault_reverse,cooldown_forward,cooldown_reverse,fault_tolerant\n";sim_steps=(int)PI("frSteps");int tested=0,passed=0;double best=-1e100;stable_sort(top.begin(),top.end(),[](const Ranked&x,const Ranked&y){return x.c.seed<0&&y.c.seed>=0;});for(auto&r:top){if(tested>=verify)break;tested++;save(r,output+"/cand-"+to_string(tested)+".txt");bool ok[2][3]={};for(int m=0;m<2;m++)for(int f=0;f<3;f++)ok[m][f]=sim(r.c,m,f);bool all=true;for(auto&row:ok)for(bool v:row)all&=v;expiry_test=true;bool cool0=sim(r.c,0,0),cool1=sim(r.c,1,0);expiry_test=false;bool normal=ok[0][0]&&ok[1][0]&&cool0&&cool1;all=all&&cool0&&cool1;csv<<r.c.seed<<','<<setprecision(12)<<r.raw<<','<<r.score<<','<<r.margin<<','<<r.c.cost;for(int f=0;f<3;f++)for(int m=0;m<2;m++)csv<<','<<ok[m][f];csv<<','<<cool0<<','<<cool1<<','<<all<<'\n';if(normal){passed++;if(r.score>best){best=r.score;save(r,output+"/best.txt");}}if(all){save(r,output+"/best-fault-tolerant.txt");}}
 ofstream stats(output+"/stats.txt");stats<<"seed="<<seed<<" attempts="<<loops<<" analytic_pass="<<screened<<" simulated="<<tested<<" normal_and_cooldown_passed="<<passed<<" budget_Qa="<<b<<"\n";if(passed)stats<<"best_score="<<best<<" see best.txt\n";else stats<<"No candidate passed normal operation and cooldown. Increase attempts or top_to_verify.\n";cerr<<"DONE seed="<<seed<<" attempts="<<loops<<" screened="<<screened<<" simulated="<<tested<<" normal_and_cooldown_passed="<<passed<<" -> "<<output<<'\n';return 0;}
